<script setup>
import { ref, computed } from 'vue'
import Icon from '../components/Icon.vue'
import Trend from '../components/Trend.vue'
import Chart from '../components/Chart.vue'
import Toolbar from '../components/Toolbar.vue'
import { revenue, orders } from '../data'
const emit = defineEmits(['action', 'customize'])
const range = ref('Last 30 days')
const factor = computed(() => range.value === 'Last 7 days' ? .25 : range.value === 'Last 90 days' ? 2.8 : 1)
const tick = n => { const a = (n / 60 * 280 + 130) * Math.PI / 180; return { x1: 140 + Math.cos(a) * 97, y1: 140 + Math.sin(a) * 97, x2: 140 + Math.cos(a) * 120, y2: 140 + Math.sin(a) * 120 } }
</script>
<template><div class="dashboard dashboard-six">
  <div class="page-title"><h1>Good afternoon</h1><Toolbar v-model="range" :date="range === 'Last 7 days' ? 'Oct 19 – Oct 25, 2026' : range === 'Last 90 days' ? 'Jul 28 – Oct 25, 2026' : 'Sep 26 – Oct 25, 2026'" @customize="$emit('customize')" @more="kind => emit('action', {title: kind === 'date' ? 'Reporting period' : 'Dashboard options', body: 'Choose a reporting period from the time range menu. All figures reflect the selected period.'})"/></div>
  <div class="finance-layout"><div class="finance-main">
    <div class="finance-kpis grid three"><div v-for="(k, i) in [['Repeat purchase rate','38.4%','2.7%'],['Orders', Math.round(1842 * factor).toLocaleString(), '4.1%'],['Average order value','$154.60','1.3%']]" :key="k[0]"><p>{{ k[0] }}</p><h2>{{ k[1] }}</h2><Trend :value="k[2]" :negative="i === 2" plain suffix="vs prior 30 days"/></div></div>
    <section class="finance-revenue"><div class="section-summary"><div><h2>${{ Math.round(92 * factor) }}K</h2><p>Monthly recurring revenue</p></div><Trend value="27.4%" plain suffix="over last 30 days"/></div><Chart :values="revenue" smooth :max="100" :height="260" :labels="['Apr 11','Apr 18','Apr 26','May 3','May 10']" :y-labels="['100k','80k','60k','40k','20k','0']"/></section>
    <div class="finance-insights grid two"><section class="ai-card"><div class="section-title"><h3><Icon name="cohort"/>AI Insights</h3><button class="text-button" @click="emit('action', {title: 'AI Insights', body: 'Unused budget runway improved by 3.5% this month. Subscription revenue is stable, while repeat purchases increased 2.7%.'})"><Icon name="cohort"/>Ask AI</button></div><p class="insight-copy">Unused budget runway improved by <strong>3.5% this month</strong> vs. trailing burn.</p></section><section class="budget-card"><div class="section-title"><span>Budget usage</span><button class="text-button" @click="emit('action', {title: 'Manage budget', type: 'budget', amount: 50734})"><Icon name="layers"/>Manage Budget</button></div><h2>$50,734</h2><div class="distribution-labels"><span>50%</span><span>25%</span><span>25%</span></div><div class="distribution"><span style="flex:2;background:#888"></span><span style="flex:1;background:#555"></span><span style="flex:1;background:#3d3d3d"></span></div><div class="legend"><span>Unused</span><span>Used</span><span>Reserved</span></div></section></div>
    <section class="finance-orders"><div class="section-summary"><div><h2>{{ Math.round(1842 * factor).toLocaleString() }}</h2><p>Orders in the last {{ range === 'Last 7 days' ? 7 : range === 'Last 90 days' ? 90 : 30 }} days</p></div><div class="align-right"><small>Peak <strong>82 on May 10</strong></small><br><Trend value="9.8%" plain suffix="over last 30 days"/></div></div><Chart :values="orders" type="bars" :height="295" :max="100" :grid="false" :y-labels="['100','75','50','25','0']" :labels="['Apr 14','Apr 19','Apr 24','Apr 29','May 4','May 9']"/></section>
  </div><aside class="finance-aside">
    <section class="revenue-gauge"><div class="gauge"><svg viewBox="0 0 280 280" role="img" aria-label="73 percent subscription revenue"><line v-for="n in 61" :key="n" v-bind="tick(n - 1)" :stroke="n < 45 ? '#888' : '#292929'" stroke-width="5" stroke-linecap="round"/></svg><div class="gauge-center"><span class="round-icon"><Icon name="wallet"/></span><p>Total Revenue</p><strong>$284,920.00</strong></div></div><div class="legend"><span>Subscriptions</span><span>Usage & services</span></div><button class="full-button" @click="emit('action', {title: 'Revenue breakdown', body: 'Subscriptions account for 73.0% of total revenue ($207,991.60). Usage and services account for 27.0% ($76,928.40).'})">View Detail<Icon name="arrow"/></button></section>
    <section class="active-customers"><p>Active customers</p><h2>2,540</h2><div class="customer-meter"><span v-for="n in 64" :key="n" :class="{ dim: n > 50 }"></span><small>78%</small></div><div class="legend"><span>Paid</span><span>Free</span></div></section>
    <section class="tax-summary"><p>Federal Income Tax</p><dl><div><dt>Date:</dt><dd>March 24, 2025</dd></div><div><dt>Amount:</dt><dd>$1,450.00</dd></div><div><dt>Payment method:</dt><dd>**** 4432</dd></div><div><dt>Status:</dt><dd><span class="neutral-pill">Completed</span></dd></div></dl><button class="full-button" @click="emit('action', {title: 'Federal Income Tax', body: 'Payment of $1,450.00 completed on March 24, 2025 using the payment method ending in 4432. Reference: TAX-2025-0324.'})">View Details<Icon name="arrow"/></button></section>
    <section class="attention-list"><p>Needs attention</p><button v-for="item in [['card','Retry failed payments',3],['campaign','Draft campaigns',5],['plug','Webhook delivery errors',1],['alert','Low inventory SKUs',2],['cart','Unfulfilled orders',12]]" :key="item[1]" @click="emit('action', {title: item[1], body: `${item[2]} items need your attention. This is a visual dashboard demo using local sample data.`})"><Icon :name="item[0]"/><span>{{ item[1] }}</span><b>{{ item[2] }}</b><Icon name="right" :size="13"/></button></section>
  </aside></div>
</div></template>
